insert into public.programs (id, kind, name, college, catalog, min_total_credits, min_gpa, notes, source_url, sort_order, excluded_programs) values
('minor-accounting', 'minor', 'Accounting Minor', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'No application; tell your advisor so it''s tracked on your degree audit. At least 6 credit hours must be upper-division. Up to 6 hours of transfer or exam credit. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/accounting', 100, array['spec-accounting']::text[]),
('minor-business', 'minor', 'Business Minor (non-business majors)', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'For non-business majors only. Prerequisites: college algebra (MATH 1130/1148 or placement M+) and ECON 2001.01. No application. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/business-minor', 101, array['fisher-bsba']::text[]),
('minor-business-analytics', 'minor', 'Business Analytics Minor (admitted Autumn 2026 and after)', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'Students admitted Spring 2026 or earlier may switch to this version through their advisor. No substitutions for required courses; up to 3 hours of equivalent transfer credit. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/business-analytics', 102, '{}'::text[]),
('minor-business-analytics-legacy', 'minor', 'Business Analytics Minor (admitted Spring 2026 and before)', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'Juniors may take the Industry Cluster courses (BUSADM 3630.05, 3632.05) through the Industry Immersion Program before the core. No substitutions for required courses; up to 3 hours of equivalent transfer credit. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/business-analytics', 103, '{}'::text[]),
('minor-entrepreneurship', 'minor', 'Entrepreneurship Minor', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'No application; your college advisor approves the completed minor. Internship courses may count as practicum electives with the minor director''s approval. Many electives have their own prerequisites. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/entrepreneurship', 104, '{}'::text[]),
('minor-insurance', 'minor', 'Insurance Minor', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'Prerequisites: college algebra (MATH 1130/1148 or placement M or L) and ECON 2001.01. Students are encouraged, not required, to take electives from all three disciplines. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/insurance', 105, '{}'::text[]),
('minor-international-business', 'minor', 'International Business Minor', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, '15-16.5 credit hours. Take BUSMHR 2000 before the other core courses; all prerequisites must be done first. Minor courses can''t count toward the business core or specialization, except as free electives. No foreign language courses. Other internationally focused electives need approval from Professor Mona Makhija. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/international-business', 106, array['spec-international-business']::text[]),
('minor-real-estate', 'minor', 'Real Estate Minor', 'Fisher College of Business', 'Fisher minor requirements (2026)', 15, 2.0, 'Prerequisite: ECON 2001 or ECON 2002. BUSFIN 3400''s BUSMHR 2292 prerequisite may be waived for declared Real Estate minors (email undergraduate@fisher.osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass. Up to 6 credit hours may overlap with the GE. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors. 1000-level courses don''t count.', 'https://fisher.osu.edu/undergraduate/academics/minors/real-estate', 107, array['spec-real-estate']::text[])
