-- Generated by scripts/fisher_requirements.py (minors). Edit that file, not this one.
begin;
delete from public.requirement_groups where program_id in (select id from public.programs where kind in ('minor'));
update public.student_profiles set specialization_id = null where specialization_id in (select id from public.programs where kind in ('minor') and id not in ('minor-accounting', 'minor-business', 'minor-business-analytics', 'minor-business-analytics-legacy', 'minor-entrepreneurship', 'minor-insurance', 'minor-international-business', 'minor-real-estate'));
delete from public.programs where kind in ('minor') and id not in ('minor-accounting', 'minor-business', 'minor-business-analytics', 'minor-business-analytics-legacy', 'minor-entrepreneurship', 'minor-insurance', 'minor-international-business', 'minor-real-estate');
on conflict (id) do update set kind = excluded.kind, name = excluded.name, college = excluded.college, catalog = excluded.catalog, min_total_credits = excluded.min_total_credits, min_gpa = excluded.min_gpa, notes = excluded.notes, source_url = excluded.source_url, sort_order = excluded.sort_order, excluded_programs = excluded.excluded_programs;
commit;
